import json

class Document:
    def __init__(self, id: str, content: dict, _etag: str = None):
        self.id = id
        self.content = content
        self._etag = _etag

    def to_dict(self):
        doc = {"id": self.id}
        doc.update(self.content)
        if self._etag:
            doc["_etag"] = self._etag
        return doc

    @classmethod
    def from_dict(cls, data: dict):
        return cls(id=data["id"], content={k: v for k, v in data.items() if k not in ["id", "_etag"]}, _etag=data.get("_etag"))

import os
from openai import OpenAI

OPENAI_API_KEY = os.environ.get("OPENAI_API_KEY")
OPENAI_MODEL_NAME = os.environ.get("OPENAI_MODEL_NAME", "gpt-3.5-turbo")

def summarize_record(record_content: str) -> str:
    if not OPENAI_API_KEY:
        raise ValueError("OPENAI_API_KEY environment variable must be set.")

    client = OpenAI(api_key=OPENAI_API_KEY)

    response = client.chat.completions.create(
        model=OPENAI_MODEL_NAME,
        messages=[
            {"role": "system", "content": "You are a helpful assistant that summarizes document records concisely."}, 
            {"role": "user", "content": f"Please summarize the following document record:\n\n{record_content}"}
        ]
    )

    return response.choices[0].message.content.strip()

import os
import requests
import uuid

AZURE_TRANSLATOR_ENDPOINT = os.environ.get("AZURE_TRANSLATOR_ENDPOINT")
AZURE_TRANSLATOR_KEY = os.environ.get("AZURE_TRANSLATOR_KEY")
AZURE_TRANSLATOR_REGION = os.environ.get("AZURE_TRANSLATOR_REGION") # e.g., "global" or "westus2"

def translate_text(text: str, target_language: str, source_language: str = "en") -> str:
    if not AZURE_TRANSLATOR_ENDPOINT or not AZURE_TRANSLATOR_KEY or not AZURE_TRANSLATOR_REGION:
        raise ValueError("AZURE_TRANSLATOR_ENDPOINT, AZURE_TRANSLATOR_KEY, and AZURE_TRANSLATOR_REGION environment variables must be set.")

    path = '/translate'
    constructed_url = AZURE_TRANSLATOR_ENDPOINT + path

    params = {
        'api-version': '3.0',
        'from': source_language,
        'to': [target_language]
    }

    headers = {
        'Ocp-Apim-Subscription-Key': AZURE_TRANSLATOR_KEY,
        'Ocp-Apim-Subscription-Region': AZURE_TRANSLATOR_REGION,
        'Content-type': 'application/json',
        'X-ClientTraceId': str(uuid.uuid4())
    }

    body = [{
        'text': text
    }]

    request = requests.post(constructed_url, params=params, headers=headers, json=body)
    response = request.json()

    if request.status_code != 200:
        raise Exception(f"Azure Translator API error: {response}")

    return response[0]['translations'][0]['text']
